:center}.joystick-group{display:flex;justify-content:space-around;align-items:center}.stick-wrap{text-align:center}.stick-label{font:9px var(--mono);letter-spacing:1px;color:#bbccc5;margin-bottom:8px}.stick{width:91px;height:91px;border-radius:50%;position:relative;background:radial-gradient(circle,#193b45 0%,#102d38 58%,#0b202b 60%);border:1px solid rgba(222,239,222,.25);touch-action:none;box-shadow:inset 0 0 0 8px rgba(223,241,227,.025),0 6px 25px rgba(0,0,0,.2)}.stick:before,.stick:after{content:'';position:absolute;background:rgba(221,239,222,.14)}.stick:before{width:1px;left:50%;top:9px;bottom:9px}.stick:after{height:1px;top:50%;left:9px;right:9px}.stick-knob{position:absolute;width:34px;height:34px;border-radius:50%;left:50%;top:50%;transform:translate(-50%,-50%);z-index:1;background:radial-gradient(circle at 35% 30%,#eaff9b,#bad547 70%);box-shadow:0 3px 12px rgba(0,0,0,.45);border:2px solid rgba(255,255,255,.4)}.stick.active{border-color:var(--lime)}.control-middle{display:flex;align-items:center;justify-content:center;gap:22px}.meter-stack{width:100%;max-width:240px}.bar-title{display:flex;justify-content:space-between;font:9px var(--mono);letter-spacing:1px;margin-bottom:6px}.bar-title b{color:var(--lime);font-weight:400}.bar-track{height:6px;background:#29434a;margin-bottom:10px;overflow:hidden}.bar-fill{height:100%;transition:width .15s}.balance-fill{background:linear-gradient(90deg,#f78370,#ecd26c,#d8f36a)}.stamina-fill{background:linear-gradient(90deg,#e77763,#e4cb69,#c9ec6e)}.pace-column{display:flex;align-items:center;gap:12px}.pace-slider{appearance:none;writing-mode:vertical-lr;direction:rtl;width:7px;height:106px;background:linear-gradient(180deg,#ef876a,#d9f36a);outline:none;border-radius:5px}.pace-slider::-webkit-slider-thumb{appearance:none;width:19px;height:19px;border-radius:50%;background:#f5f4e8;border:3px solid #95ae59;box-shadow:0 2px 6px #001}.pace-info{font:9px var(--mono);color:#b7c8c0;line-height:1.6}.pace-info b{font:20px var(--displa