tle">PRÓXIMA PROVA</h3><p style="color:#a6bbb4;font-size:10px">${save.wins<3?'Regata estadual · 500 m':'Campeonato nacional · 1.000 m'}</p><button class="btn btn-primary" id="careerRace">ACEITAR DESAFIO →</button></div></div></div></div>`;$('#offerBtn').onclick=clubOffers;$('#trainBtn').onclick=()=>upgrade('train');$('#careerRace').onclick=showModes}
