function renderGarage(){const v=$('#garage');v.innerHTML=`<div class="panel-page"><div class="eyebrow">OFICINA DO CLUBE · ${save.club.toUpperCase()}</div><h1 class="page-heading">ATLETA &amp; BARCO.</h1><p class="page-desc">Cada detalhe faz diferença. Invista suas premiações em treinamento e em um barco que responda a cada remada.</p><div class="career-layout"><div class="info-card"><h3 class="info-title">FICHA DO REMADOR</h3>${[['Força · potência na água','strength'],['Equilíbrio · estabilidade','balance'],['Resistência · fôlego','endurance'],['Técnica · eficiência','technique']].map(x=>`<div class="mission"><span>${x[0]}</span><small>${save[x[1]]}/100</small></div><div class="meter"><i style="width:${save[x[1]]}%"></i></div>`).join('')}<button class="btn btn-primary" id="trainBtn" style="margin-top:18px">PLANO DE TREINO · ◈ 250</button></div><div class="info-card"><h3 class="info-title">UPGRADE DO BARCO</h3><p style="font-size:11px;color:#a6bbb4;line-height:1.8">O casco define seu potencial. Cada material reduz o arrasto e aumenta a velocidade máxima.</p>${[['Fibra de vidro','+4% velocidade · ◈ 350'],['Carbono','+9% velocidade · ◈ 800'],['Carbono ultraleve','+15% velocidade · ◈ 1.500']].map((x,i)=>`<div class="offer-card" style="padding:12px 0;border:0;border-bottom:1px solid var(--line);background:none"><div class="offer-crest">${i+1}</div><div class="offer-info"><strong>${x[0]}</strong><small>${x[1]}</small></div><button class="btn btn-ghost" style="padding:8px" data-boat="${i}">${save.boat>=i+1?'EQUIPADO':'MELHORAR'}</button></div>`).join('')}<button class="btn btn-ghost" id="customBtn" style="margin-top:12px">EDITAR REMADOR &amp; CORES</button></div></div></div>`;$('#trainBtn').onclick=()=>upgrade('train');$('#customBtn').onclick=customize;$$('[data-boat]').forEach(b=>b.onclick=()=>upgrade('boat',+b.dataset.boat))}
function upgrade(type,index=0){if(type==='train'){if(save.cash<250){toast('MOEDAS INSUFICIENTES');return}save.cash-=250;save.strength=Math.min(100,save.strength+4);save.balance=Math.min(100,save.balance+4);save.endurance=Math.min(100,save.endurance+5);save.technique=Math.min(100,save.technique+4)}else{let cost=[350,800,1500][index];if(save.boat>=index+1)return;if(save.cash<cost){toast('MOEDAS INSUFICIENTES');return}save.cash-=cost;save.boat=index+1}persist();renderGarage();toast('UPGRADE CONFIRMADO · BOM TREINO!')}
