@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&family=Oswald:wght@500;600;700&display=swap');
:root{--ink:#071a24;--panel:#0d2632;--panel2:#12313d;--line:rgba(207,231,222,.13);--cream:#f2f1e8;--muted:#a9beb9;--lime:#d8f36a;--orange:#f7a16b;--blue:#77d6e5;--serif:Georgia,serif;--sans:'Manrope',sans-serif;--display:'Oswald',sans-serif;--mono:'DM Mono',monospace}

*{box-sizing:border-box}
html,body{margin:0;width:100%;height:100%;overflow:hidden;background:var(--ink);color:var(--cream);font-family:var(--sans)}
button{font:inherit;color:inherit;cursor:pointer}
#app{height:100dvh;min-height:520px;position:relative;overflow:hidden;background:radial-gradient(ellipse at 68% 32%,#245361 0%,#102d38 44%,#081d28 78%)}

#scene{position:absolute;inset:0;width:100%;height:100%;z-index:0}
.shade{position:absolute;inset:0;z-index:1;pointer-events:none;background:linear-gradient(90deg,rgba(5,20,29,.92) 0%,rgba(5,20,29,.55) 40%,rgba(5,20,29,.02) 75%),linear-gradient(0deg,rgba(5,20,29,.7) 0%,transparent 42%,rgba(5,20,29,.2) 100%)}

.topbar{height:76px;position:absolute;z-index:5;top:0;left:0;right:0;display:flex;align-items:center;padding:0 4.2vw;border-bottom:1px solid rgba(235,247,233,.12);background:linear-gradient(180deg,rgba(5,21,29,.7),transparent);gap:38px}
.brand{display:flex;align-items:center;gap:12px;min-width:220px}
