.brand-name{font-family:var(--display);font-size:18px;font-weight:600;letter-spacing:1.6px;line-height:1}
.brand-sub{font-family:var(--mono);font-size:8px;letter-spacing:2px;color:var(--muted);margin-top:5px}
.nav{display:flex;align-items:center;gap:27px;height:100%}
.nav button{background:none;border:0;color:#9eb3b1;font-size:10px;font-weight:800;letter-spacing:1.4px;height:100%;position:relative}
.nav button.active,.nav button:hover{color:var(--cream)}
.nav button.active:after{content:'';position:absolute;bottom:0;left:0;right:0;height:2px;background:var(--lime)}
.topright{margin-left:auto;display:flex;align-items:center;gap:18px}
