.coin{color:var(--lime);font-size:17px}
.avatar{width:37px;height:37px;border:1px solid #81958c;border-radius:50%;display:grid;place-items:center;font-size:12px;color:var(--lime);background:#193841}

.view{position:absolute;inset:0;z-index:2;display:none}
.view.active{display:block}
.lobby-content{position:absolute;left:8.1vw;top:19%;width:345px;z-index:3}
.eyebrow{font-family:var(--mono);color:var(--lime);font-size:10px;letter-spacing:2px;text-transform:uppercase;display:flex;align-items:center;gap:9px}
.eyebrow:before{content:'';width:22px;height:1px;background:var(--lime)}
.title{font:600 clamp(48px,5.4vw,78px)/.93 var(--display);letter-spacing:-1px;margin:17px 0 15px;text-transform:uppercase}
.title em{font-style:normal;color:var(--lime)}
.intro{max-width:320px;color:#b8c9c4;font-size:12px;line-height:1.8}
.club-chip{margin-top:24px;padding:13px 15px;border:1px solid rgba(217,243,106,.3);background:linear-gradient(90deg,rgba(15,43,51,.88),rgba(15,43,51,.35));display:flex;align-items:center;gap:12px;width:290px}
.club-emblem{width:34px;height:40px;border:1px solid #f1cf80;color:#f1cf80;display:grid;place-items:center;font-family:var(--display);font-size:18px;clip-path:polygon(0 0,100% 0,100% 75%,50% 100%,0 75%)}
.club-caption{color:#8ea8a4;font:9px var(--mono);letter-spacing:1px}
.club-name{font-size:12px;font-weight:800;margin-top:3px}
.stars{color:#f3cb78;letter-spacing:2px;font-size:11px;margin-left:auto}
.hero-actions{display:flex;gap:11px;margin-top:21px}
.btn{border:0;min-height:45px;padding:0 19px;font-size:10px;font-weight:800;letter-spacing:1.1px;text-transform:uppercase;transition:.18s;display:inline-flex;align-items:center;justify-content:center;gap:10px}
.btn-primary{background:var(--lime);color:#13282b}
