.btn-ghost:hover{border-color:var(--lime);color:var(--lime)}
.small-meta{font:9px var(--mono);color:#93aaa5;letter-spacing:1px;margin-top:25px}
.small-meta strong{color:var(--cream);font-weight:500}
.lobby-stats{position:absolute;right:5.2vw;top:102px;z-index:3;width:215px}
.stat-card{background:rgba(7,25,33,.52);border:1px solid rgba(233,246,233,.15);padding:17px 18px;margin-bottom:9px;backdrop-filter:blur(8px)}
.stat-head{display:flex;justify-content:space-between;color:#91aaa4;font:9px var(--mono);letter-spacing:1px}
.stat-value{font:600 25px var(--display);margin-top:6px}
.stat-value small{font:10px var(--mono);color:var(--muted);margin-left:4px}
.meter{height:3px;background:#31505a;margin-top:10px}
