.trophy-strip{position:absolute;right:5.2vw;bottom:6%;z-index:3;display:flex;gap:8px}
.trophy{height:44px;width:44px;display:grid;place-items:center;border:1px solid rgba(225,237,221,.2);background:rgba(6,23,31,.45);font-size:17px;filter:grayscale(1);opacity:.5}
.trophy.earned{filter:none;opacity:1;border-color:#e8c66f}
.bottom-note{position:absolute;left:8.1vw;bottom:5.5%;font:9px var(--mono);color:#9bb2ad;letter-spacing:1.4px;z-index:3}
.bottom-note b{color:var(--lime);font-weight:400}

.panel-page{position:absolute;inset:76px 0 0;padding:5.5vh 7vw;overflow:auto;background:linear-gradient(110deg,rgba(6,23,31,.94),rgba(7,25,33,.82) 52%,rgba(8,27,35,.38));}
.page-heading{font:600 clamp(35px,4vw,55px)/1 var(--display);text-transform:uppercase;margin:12px 0 8px}
.page-desc{font-size:12px;color:#a8bcb7;max-width:530px;line-height:1.75}
