function startRace(mode='Regata',training=false){let meta=modes.find(m=>m[0]===mode)||modes[1],distance=mode==='Campeonato'?1000:mode==='Seletiva olímpica'?2000:500;if(mode==='Seletiva olímpica'&&save.wins<6){toast('CONQUISTE 6 VITÓRIAS PARA A SELETIVA');return}race={mode,training,distance,distanceDone:0,elapsed:0,stamina:100,drive:.05,pace:30,strokes:0,pairs:0,good:0,lastArm:{left:-9,right:-9},active:{left:false,right:false},balance:100,opponents:[{time:distance/(7.4+Math.random()*1.5)},{time:distance/(8.2+Math.random()*2)},{time:distance/(8.8+Math.random()*2)}],finished:false,rank:1,lastStroke:0};$('#app').classList.add('racing');go('race');$('#race').innerHTML=raceMarkup();$('#raceTitle').textContent=mode.toUpperCase();$('#raceSub').textContent=`${distance.toLocaleString('pt-BR')} M · ${training?'TREINO LIVRE':'REGATA OFICIAL'} · ${save.club.toUpperCase()}`;$('#progressMark').textContent=`${distance} M`;$('#raceDistance').innerHTML=`${distance}<small>METROS RESTANTES</small>`;$('#quitRace').onclick=()=>modal('PAUSA DA PROVA','Deseja sair da água?','Seu resultado não será salvo se abandonar esta prova.',`<button class="btn btn-ghost" data-action="lobby">CONTINUAR REMANDO</button><button class="btn btn-primary" data-action="abandon">ABANDONAR</button>`);$('#paceSlider').oninput=e=>{race.pace=+e.target.value;$('#paceValue').textContent=race.pace};bindControls();updateRaceHUD();toast('PUXE E SOLTE OS DOIS REMOS!')}
